// Registro experimental: intervalos MQTT, no latencia de red.
if (msg.reset) { context.set('s',null); node.status({fill:'grey',shape:'ring',text:'Listo para iniciar'}); return [null,{payload:'CONTADOR REINICIADO'}]; }
const d = msg.payload;
if (!d || typeof d !== 'object' || !Number.isFinite(Number(d.posicion))) return null;
const now = Date.now();
let s = context.get('s');
if (!s || msg.reset) s = {inicio:now, previo:null, n:0, huecos:0, cambios:0, ultimoEstado:null, maxIntervalo:0, anomalias:0};
if (now-s.inicio > 30*60*1000) {
    if (!s.terminado) { s.terminado=true; node.status({fill:'green',shape:'ring',text:'30 min completados'}); context.set('s',s); return [null,{payload:{resultado:'FIN',muestras:s.n,huecos_mayor_2s:s.huecos,cambios_estado:s.cambios,intervalo_max_ms:s.maxIntervalo,anomalias:s.anomalias}}]; }
    return null;
}
let intervalo = s.previo===null ? null : now-s.previo;
if (intervalo!==null) {
  s.maxIntervalo=Math.max(s.maxIntervalo,intervalo);
  if (intervalo>2000) s.huecos++;
}
if (s.ultimoEstado!==null && s.ultimoEstado!==d.estado) s.cambios++;
if (![1,2,3].includes(Number(d.piso)) || ![1,2,3].includes(Number(d.destino)) || Number(d.posicion)<0 || Number(d.posicion)>400) s.anomalias++;
s.n++; s.previo=now; s.ultimoEstado=d.estado;
context.set('s',s);
const elapsed=((now-s.inicio)/60000).toFixed(2);
node.status({fill:'blue',shape:'dot',text:`${elapsed} min | ${s.n} muestras | ${s.huecos} huecos`});
const header = s.n===1 ? 'fecha_utc,minutos,piso,destino,estado,posicion,emergencia,tiempo_esp_ms,intervalo_recibido_ms,huecos,anomalias\n' : '';
const line=header+[new Date(now).toISOString(),elapsed,d.piso,d.destino,d.estado,d.posicion,d.emergencia, d.tiempo_ms,intervalo===null?'':intervalo,s.huecos,s.anomalias].join(',')+'\n';
return [{payload:line,filename:'elevador_prueba_30min.csv'}, {payload:{minutos:elapsed,muestras:s.n,huecos_mayor_2s:s.huecos,intervalo_max_ms:s.maxIntervalo,cambios_estado:s.cambios,anomalias:s.anomalias}}];
